	// layout: i = row index (outer), j = column index (inner)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimization notes:
// - We keep the lexicographic update order (i outer, j inner) to preserve
//   Gauss–Seidel semantics exactly as in the original polybench kernel.
// - We pre-build a traverser for the interior points so it is reused for all
//   time-steps; this avoids reconstructing the same traversal description in
//   every iteration of the time loop.
// - We hoist the constant 1/9 out of the innermost loops.
// - We still use Noarr states and A[state] accesses exclusively, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Degenerate cases (too small domain or zero steps) – do nothing.
	if (tsteps <= 0 || n_i <= 2 || n_j <= 2)
		return;

	// Hoisted reciprocal of 9 – avoids a division in the inner loop.
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Pre-build a traverser restricted to interior points: i, j in [1, n-2].
	// Order is still row-major: i (outer), j (inner).
	//
	// Using `order(slice<...>)` here keeps the original indices in the
	// state (1 .. n-2), which is important because we apply `neighbor(...)`
	// relative to those indices inside the loop body.
	auto interior_trav =
		traverser(A)
			.order(slice<'i'>(1, n_i - 2) ^ slice<'j'>(1, n_j - 2));

	#pragma scop
	for (int t = 0; t < tsteps; ++t) {
		// Traverse only interior points, in the same lexicographic order
		// as the original nested for-loops (i outer, j inner).
		interior_trav.for_each([&](auto state) {
			// Current center point (i, j)
			auto s = state;

			// Build neighbor states. We first move in i- and j-directions,
			// then reuse those shifted states for the diagonals. This keeps
			// the code clear and avoids re-specifying both deltas every time.
			auto s_im1_j   = neighbor<'i'>(s, -1);
			auto s_ip1_j   = neighbor<'i'>(s, +1);
			auto s_i_jm1   = neighbor<'j'>(s, -1);
			auto s_i_jp1   = neighbor<'j'>(s, +1);

			auto s_im1_jm1 = neighbor<'j'>(s_im1_j, -1);
			auto s_im1_jp1 = neighbor<'j'>(s_im1_j, +1);
			auto s_ip1_jm1 = neighbor<'j'>(s_ip1_j, -1);
			auto s_ip1_jp1 = neighbor<'j'>(s_ip1_j, +1);

			// 9-point Seidel stencil (8 neighbors + center)
			num_t sum =
				A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
				A[s_i_jm1]   + A[s]       + A[s_i_jp1] +
				A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

			A[s] = sum * inv9;
		});
	}
	#pragma endscop
}

} // namespace


