		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimizations (while preserving the original Gauss–Seidel semantics):
// - Pre-build the proto-structure describing the interior domain so it is
//   reused for every time step, instead of reconstructing the slices each time.
// - Use explicit state arithmetic (s +/- idx<'i'>(1), s +/- idx<'j'>(1))
//   instead of calling neighbor<...> repeatedly. This keeps all accesses
//   expressed via Noarr states (A[state]) but reduces some template traffic
//   and makes the data-flow clearer.
// - The traversal order in (i, j) is kept identical to the original:
//   i is still the outer loop, j the inner loop, and only interior
//   points 1 .. n-2 are visited.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	std::size_t n_i = A | get_length<'i'>();
	std::size_t n_j = A | get_length<'j'>();

	// Pre-build the interior domain once:
	// i, j in [1, n-2]. Using `order` keeps the state indices equal to the
	// original (1 .. n-2), which is important for safe neighbor arithmetic.
	auto interior =
		slice<'i'>(std::size_t(1), n_i - 2) ^
		slice<'j'>(std::size_t(1), n_j - 2);

	// Precompute unit index shifts as states; they are reused in the inner loop.
	const auto di = idx<'i'>(std::size_t(1));
	const auto dj = idx<'j'>(std::size_t(1));

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only the interior points: i, j in [1, n-2]
		// The `interior` proto is applied via `order`, so the state seen in
		// the lambda uses the original indices (1 .. n-2), suitable for
		// state arithmetic with di/dj.
		traverser(A)
			.order(interior)
			.for_each([&](auto state) {
				// Center point (i, j)
				const auto s = state;

				// Direct neighbors in i and j directions
				const auto s_im1 = s - di; // (i-1, j)
				const auto s_ip1 = s + di; // (i+1, j)
				const auto s_jm1 = s - dj; // (i,   j-1)
				const auto s_jp1 = s + dj; // (i,   j+1)

				// Diagonal neighbors
				const auto s_im1_jm1 = s_im1 - dj; // (i-1, j-1)
				const auto s_im1_jp1 = s_im1 + dj; // (i-1, j+1)
				const auto s_ip1_jm1 = s_ip1 - dj; // (i+1, j-1)
				const auto s_ip1_jp1 = s_ip1 + dj; // (i+1, j+1)

				// 9-point stencil: sum of center + 8 neighbors
				num_t sum =
					A[s_im1_jm1] + A[s_im1] + A[s_im1_jp1] +
					A[s_jm1]     + A[s]     + A[s_jp1] +
					A[s_ip1_jm1] + A[s_ip1] + A[s_ip1_jp1];

				A[s] = sum / num_t(9.0);
			});
	}
	#pragma endscop
