		slice<'j'>(1, interior_j_len);

	// reciprocal of 9.0 used in the stencil update
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	#pragma scop
	for (int t = 0; t < tsteps; ++t) {
		// Traverse only interior points: i, j in [1, n-2]
		// Traversal order is i-major, j-minor, matching the
		// original triple-loop nest and thus preserving
		// Gauss–Seidel update semantics.
		noarr::traverser(A)
			.order(interior)
			.for_each([&](auto state) {
				// Extract current coordinates
				auto [i, j] = get_indices<'i', 'j'>(state);

				// All indices are interior, so neighbors are within bounds
				const std::size_t im1 = i - 1;
				const std::size_t ip1 = i + 1;
				const std::size_t jm1 = j - 1;
				const std::size_t jp1 = j + 1;

				// Load 3x3 neighborhood around (i,j).
				// We access the center once via A[state] and
				// all other neighbors via idx<'i','j'>(...).
				const num_t a_im1_jm1 = A[noarr::idx<'i', 'j'>(im1, jm1)];
				const num_t a_im1_j   = A[noarr::idx<'i', 'j'>(im1, j   )];
				const num_t a_im1_jp1 = A[noarr::idx<'i', 'j'>(im1, jp1)];

				const num_t a_i_jm1   = A[noarr::idx<'i', 'j'>(i,   jm1)];
				const num_t a_i_j     = A[state]; // center
				const num_t a_i_jp1   = A[noarr::idx<'i', 'j'>(i,   jp1)];

				const num_t a_ip1_jm1 = A[noarr::idx<'i', 'j'>(ip1, jm1)];
				const num_t a_ip1_j   = A[noarr::idx<'i', 'j'>(ip1, j   )];
				const num_t a_ip1_jp1 = A[noarr::idx<'i', 'j'>(ip1, jp1)];

				const num_t sum =
					a_im1_jm1 + a_im1_j + a_im1_jp1 +
					a_i_jm1   + a_i_j   + a_i_jp1 +
					a_ip1_jm1 + a_ip1_j + a_ip1_jp1;

				// Seidel update: in-place Gauss–Seidel, time step t
				A[state] = sum * inv9;
			});
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
